import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import test from 'node:test';
test('passing inspection unlocks sample generation and adoption without losing reference',async()=>{const {ctx,app}=setup();vm.runInContext("toast=()=>{};home=false;s.step=5;s.maxStep=4;s.checked=true;s.warnings=true;s.noImage=true;s.items[5].price=36;Ref.choose(s,'hero');s.reference.analysis.status='ready';s.reference.interpreted=true;render()",ctx);assert.doesNotMatch(app.innerHTML,/<button[^>]*data-action="ref-samples"[^>]*disabled/);await vm.runInContext("referenceAction('samples','')",ctx);assert.equal(vm.runInContext('s.reference.samples',ctx),true);await vm.runInContext("referenceAction('confirm','')",ctx);assert.equal(vm.runInContext('M.canContinue(s)',ctx),true);await vm.runInContext("act('next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),6);assert.equal(vm.runInContext('s.reference.id',ctx),'hero');});
function setup(){const app={innerHTML:''},main={scrollTop:0,scrollTo(){}},dialog={close(){},showModal(){}},store=new Map(),ctx=vm.createContext({console,structuredClone,setTimeout,clearTimeout,URL,document:{querySelector(sel){return sel==='#app'?app:sel==='.main'?main:sel==='#dialog'?dialog:null},addEventListener(){}},localStorage:{getItem:k=>store.get(k)||null,setItem:(k,v)=>store.set(k,v)}});ctx.window=ctx;ctx.addEventListener=()=>{};for(const file of ['model.js','menu-renderer.js','menu-layouts.js','reference-design.js','brand-materials.js','studio.js','reference-controller.js'])vm.runInContext(readFileSync(new URL(file,import.meta.url),'utf8'),ctx);return {ctx,app};}
test('new project reaches step one and persists',async()=>{const {ctx,app}=setup();await vm.runInContext("act('new-confirm','')",ctx);assert.match(app.innerHTML,/STEP 01/);assert.equal(vm.runInContext('home',ctx),false)});
test('editor controls have unique IDs even with mobile inspector',()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=7;s.maxStep=8;s.selected='d1';render()",ctx);const ids=[...app.innerHTML.matchAll(/\sid="([^"]+)"/g)].map(x=>x[1]);const controls=ids.filter(x=>x.startsWith('f-'));assert.equal(new Set(controls).size,controls.length)});
test('material edits revoke access to downstream steps',()=>{const {ctx}=setup();vm.runInContext('s.maxStep=8;s.checked=false;dirty(true)',ctx);assert.equal(vm.runInContext('s.maxStep',ctx),4)});
test('export results expose a native download link',()=>{const {ctx}=setup();const html=vm.runInContext("files=[{name:'menu.zip',url:'blob:example',blob:{size:100}}];exportView()",ctx);assert.match(html,/<a[^>]+href="blob:example"[^>]+download="menu.zip"/)});
test('step five blocks until reference samples are explicitly confirmed',()=>{const {ctx}=setup();vm.runInContext("s.step=5;s.maxStep=5;s.checked=true;s.warnings=true;s.noImage=true;s.items[5].price=36;Ref.choose(s,'hero')",ctx);assert.equal(vm.runInContext('M.canContinue(s)',ctx),false);vm.runInContext("s.reference.analysis.status='ready';s.reference.interpreted=true;s.reference.samples=true;Ref.confirm(s,0)",ctx);assert.equal(vm.runInContext('M.canContinue(s)',ctx),true)});
test('unchecked materials allow browsing direction but not downstream access',async()=>{const {ctx,app}=setup();vm.runInContext('home=false;s.step=4;s.maxStep=4;render()',ctx);assert.match(app.innerHTML,/先浏览视觉方向/);await vm.runInContext("act('goto','5')",ctx);assert.equal(vm.runInContext('s.step',ctx),5);assert.equal(vm.runInContext('s.maxStep',ctx),4);assert.match(app.innerHTML,/生成样稿前还需完成/);assert.match(app.innerHTML,/运行材料检查/);assert.match(app.innerHTML,/番茄牛肉面：请确认价格/);await vm.runInContext("act('goto','6')",ctx);assert.equal(vm.runInContext('s.step',ctx),5);await vm.runInContext("act('goto','4')",ctx);assert.equal(vm.runInContext('s.step',ctx),4);});
test('materials gate protects sample generation and adoption even after reference confirmation',async()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=5;s.maxStep=4;Ref.choose(s,'hero');s.reference.analysis.status='ready';s.reference.interpreted=true;render()",ctx);assert.match(app.innerHTML,/<button[^>]*data-action="ref-samples"[^>]*disabled/);await vm.runInContext("referenceAction('samples','')",ctx);assert.equal(vm.runInContext('s.reference.samples',ctx),false);assert.equal(vm.runInContext('busy',ctx),null);vm.runInContext('s.reference.samples=true',ctx);await vm.runInContext("referenceAction('confirm','')",ctx);assert.equal(vm.runInContext('s.reference.confirmed',ctx),false);vm.runInContext('s.reference.confirmed=true',ctx);assert.equal(vm.runInContext('M.canContinue(s)',ctx),false);});
test('material gate clears only when all requirements are met',()=>{const {ctx}=setup();vm.runInContext('s.checked=true;s.warnings=true;s.noImage=true;s.items[5].price=36',ctx);assert.equal(vm.runInContext('M.materialRequirements(s).length',ctx),0);assert.equal(vm.runInContext('M.canGenerate(s)',ctx),true);vm.runInContext('s.checked=false',ctx);assert.equal(vm.runInContext('M.canGenerate(s)',ctx),false);assert.equal(vm.runInContext('M.canVisit({...s,maxStep:3},5)',ctx),false);assert.equal(vm.runInContext('M.canVisit({...s,maxStep:4},5)',ctx),true);});
test('upstream changes invalidate reference confirmation',()=>{const {ctx}=setup();vm.runInContext("s.checked=true;s.maxStep=8;Ref.choose(s,'hero');s.reference.analysis.status='ready';s.reference.interpreted=true;s.reference.samples=true;Ref.confirm(s,0);dirty(true)",ctx);assert.equal(vm.runInContext('Ref.ready(s)',ctx),false);assert.equal(vm.runInContext('s.maxStep',ctx),5)});
test('reference layouts share export-safe editor geometry',()=>{const {ctx}=setup();for(const layout of ['hero','collage','editorial','text','grid']){vm.runInContext("s.layout='"+layout+"'",ctx);assert.equal(vm.runInContext('layoutErrors().length',ctx),0)}});
test('requirements precede products and inspection remains a gate',async()=>{const {ctx,app}=setup();await vm.runInContext("act('new-confirm','')",ctx);await vm.runInContext("act('next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),2);assert.match(app.innerHTML,/<h1>设计意图<\/h1>/);assert.doesNotMatch(vm.runInContext('intention()',ctx),/主推商品/);await vm.runInContext("act('next','')",ctx);assert.match(app.innerHTML,/<h1>菜单材料<\/h1>/);assert.match(vm.runInContext('materials()',ctx),/主推商品/);await vm.runInContext("act('next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),4);assert.equal(vm.runInContext('M.canContinue(s)',ctx),false);await vm.runInContext("act('next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),4)});
test('analysis success, correction and confirmation gate',async()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=5;s.maxStep=5;Ref.choose(s,'collage')",ctx);await vm.runInContext("referenceAction('analyze','')",ctx);assert.equal(vm.runInContext('s.reference.analysis.status',ctx),'ready');assert.equal(vm.runInContext('s.reference.interpreted',ctx),false);assert.match(app.innerHTML,/风格分析结果/);vm.runInContext("referenceChange('interpreted',true);s.reference.samples=true;Ref.confirm(s,0);referenceChange('recipe','hero')",ctx);assert.equal(vm.runInContext('Ref.ready(s)',ctx),false);assert.equal(vm.runInContext('s.reference.analysis.edited',ctx),true);assert.equal(vm.runInContext('s.reference.recipe',ctx),'hero');});
test('analysis failure and retry preserve reference and products',async()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=5;Ref.choose(s,'editorial')",ctx);await vm.runInContext("referenceAction('analysis-fail','')",ctx);assert.equal(vm.runInContext('s.reference.analysis.status',ctx),'failed');assert.match(app.innerHTML,/分析未完成/);vm.runInContext("referenceChange('interpreted',true)",ctx);assert.equal(vm.runInContext('s.reference.interpreted',ctx),false);await vm.runInContext("referenceAction('analyze','')",ctx);assert.equal(vm.runInContext('s.reference.analysis.status',ctx),'ready');assert.equal(vm.runInContext('s.reference.recipe',ctx),'editorial');assert.equal(vm.runInContext('M.items(s).length',ctx),12);});
test('cancel prevents late analysis result from changing state',async()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=5;Ref.choose(s,'hero')",ctx);const pending=vm.runInContext("referenceAction('analyze','')",ctx);assert.match(app.innerHTML,/正在分析你的参考图/);await vm.runInContext("act('cancel-job','')",ctx);await pending;assert.equal(vm.runInContext('s.reference.analysis.status',ctx),'cancelled');assert.equal(vm.runInContext('busy',ctx),null);assert.match(app.innerHTML,/分析已取消/);assert.equal(vm.runInContext('s.reference.samples',ctx),false);});
test('upload triggers analysis automatically after successful local decoding',()=>{const {ctx}=setup();ctx.testInput={files:[{name:'fixture.png',type:'image/png',size:100}],setAttribute(){},remove(){},click(){this.onchange();}};ctx.document.body={append(){}};ctx.document.createElement=tag=>tag==='input'?ctx.testInput:{getContext:()=>({drawImage(){}}),toDataURL:()=> 'data:image/png;base64,demo'};ctx.FileReader=class {readAsDataURL(){this.result='data:image/png;base64,demo';this.onload();}};ctx.Image=class {width=800;height=600;set src(value){this.onload();}};vm.runInContext("let analysisCalls=0;analyzeReference=async()=>{analysisCalls++};uploadReference()",ctx);assert.equal(vm.runInContext('analysisCalls',ctx),1);assert.equal(vm.runInContext('s.reference.name',ctx),'fixture.png');assert.equal(vm.runInContext('s.reference.source',ctx),'upload');assert.equal(vm.runInContext('s.reference.interpreted',ctx),false);});
test('device presets set native pixel export size and invalidate generated designs',async()=>{const {ctx,app}=setup();for(const [id,w,h] of [['ipad-mini-6',2266,1488],['ipad-8',2160,1620],['ipad-9',2160,1620],['screen-1920-1200',1920,1200],['screen-2000-1200',2000,1200],['ipad-10',2360,1640]]){vm.runInContext('home=false;s.step=1;s.maxStep=8;s.generated=true',ctx);await vm.runInContext(`act('profile','${id}')`,ctx);assert.equal(vm.runInContext('s.profile',ctx),id);assert.equal(vm.runInContext('M.size(s).width',ctx),w);assert.equal(vm.runInContext('M.size(s).height',ctx),h);assert.equal(vm.runInContext('s.unit',ctx),'px');assert.equal(vm.runInContext('s.generated',ctx),false);assert.equal(vm.runInContext('M.items(s).length',ctx),12);assert.match(app.innerHTML,/切换为/);await vm.runInContext("act('rotate-profile','')",ctx);assert.equal(vm.runInContext('M.size(s).width',ctx),h);assert.equal(vm.runInContext('M.size(s).height',ctx),w);assert.equal(vm.runInContext('s.profile',ctx),id);}});
test('expanded intent offers basic and advanced requirements with escaped live summary',()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=2;render()",ctx);assert.match(app.innerHTML,/新品上市/);assert.match(app.innerHTML,/套餐推荐/);assert.match(app.innerHTML,/更多设计要求/);assert.match(app.innerHTML,/每页最多 2 道/);assert.doesNotMatch(vm.runInContext('intention()',ctx),/data-field="featured"/);vm.runInContext("intentAdvancedOpen=true;s.checked=true;s.maxStep=8;s.generated=true;updateIntent('readingScene','墙面远看');updateIntent('intentNotes','<img onerror=alert(1)>')",ctx);assert.equal(vm.runInContext('s.generated',ctx),false);assert.equal(vm.runInContext('s.maxStep',ctx),5);assert.match(app.innerHTML,/墙面远看/);assert.match(app.innerHTML,/&lt;img onerror=alert\(1\)&gt;/);assert.match(app.innerHTML,/intent-advanced" open/);assert.equal(vm.runInContext("JSON.parse(localStorage.getItem(KEY)).readingScene",ctx),'墙面远看');});
test('brand material changes validate and persist while invalidating old samples',()=>{const {ctx,app}=setup();vm.runInContext("home=false;s.step=3;s.maxStep=8;s.checked=true;brandAdvancedOpen=true;changeBrand('primary','#123456')",ctx);assert.equal(vm.runInContext('s.brandMaterials.primary',ctx),'#123456');assert.equal(vm.runInContext('s.maxStep',ctx),5);assert.equal(vm.runInContext("JSON.parse(localStorage.getItem(KEY)).brandMaterials.primary",ctx),'#123456');vm.runInContext("changeBrand('primary','invalid')",ctx);assert.equal(vm.runInContext('s.brandMaterials.primary',ctx),'#123456');assert.match(app.innerHTML,/色值未保存/);assert.match(app.innerHTML,/brand-advanced" open/);vm.runInContext("changeBrand('policy','strict');changeBrand('primary','')",ctx);assert.equal(vm.runInContext('M.canContinue(s)',ctx),false);assert.match(app.innerHTML,/请提供品牌主色/);vm.runInContext("changeBrand('policy','reference')",ctx);assert.equal(vm.runInContext('M.canContinue(s)',ctx),true);});
test('invalid decorative upload retains existing asset',()=>{const {ctx,app}=setup();ctx.testInput={files:[{name:'bad.gif',type:'image/gif',size:10}],setAttribute(){},remove(){},click(){this.onchange();}};ctx.document.body={append(){}};ctx.document.createElement=()=>ctx.testInput;vm.runInContext("home=false;s.step=3;M.ensureBrand(s).decorImage='data:old';uploadBrandDecoration()",ctx);assert.equal(vm.runInContext('s.brandMaterials.decorImage',ctx),'data:old');assert.match(app.innerHTML,/原有素材已保留/);});
